const html=require("html-template-tag");module.exports=(e,t,s,r)=>(Array.isArray(t)||(t=[t]),html`
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    
    <title>Less.js Spec Runner</title>

    <!-- for each test, generate CSS/LESS link tags -->
    $${e.map(function(e){var t=e.split("/"),s=e.replace(/\/less\//g,"/css/").replace(/less$/,"css"),r=t[t.length-1].split(".")[0];return`\n    \x3c!-- the tags to be generated --\x3e\n    <link id="original-less:test-less-${r}" title="test-less-${r}" rel="stylesheet/less" type="text/css" href="../../${e}">\n    <link id="expected-less:test-less-${r}" rel="stylesheet" type="text/css" href="../../${s}">\n    `}).join("")}

    $${t.map(e=>`\n        <script src="../../${e}"><\/script>\n    `).join("")}

    <link rel="stylesheet" href="../../node_modules/mocha/mocha.css">
</head>

<body>
    <!-- content -->
    <div id="mocha"></div>
    <script src="../../node_modules/mocha/mocha.js"></script>
    <script src="../../node_modules/mocha-teamcity-reporter/lib/teamcityBrowser.js"></script>
    <script src="../../node_modules/chai/chai.js"></script>
    <script>
        expect = chai.expect
        mocha.setup({
            ui: 'bdd',
            timeout: 2500
        });
    </script>
    <script src="common.js"></script>
    <script src="../../${s}"></script>
    <script src="${r||"less.min.js"}"></script>
    <script>
        /** Saucelabs config */
        onload = function() {
            var runner = mocha.run();

            var failedTests = [];
            runner.on('end', function() {
                window.mochaResults = runner.stats;
                window.mochaResults.reports = failedTests;
            });

            runner.on('fail', logFailure);

            function logFailure(test, err){
                var flattenTitles = function(test){
                    var titles = [];
                    while (test.parent.title) {
                        titles.push(test.parent.title);
                        test = test.parent;
                    }
                    return titles.reverse();
                };

                failedTests.push({name: test.title, result: false, message: err.message, stack: err.stack, titles: flattenTitles(test) });
            };
        };
    </script>
</body>
</html>
`);